{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "We included randomised trials of people at risk of covid-19 that compared drugs, therapeutic doses of vitamins, or antibodies for prophylaxis against one another or against no prophylaxis (placebo or standard care, as defined by the researchers)... We included studies addressing people pre- or post-exposure to covid-19 and at low risk (e.g. unexposed community member) or high risk (e.g. member of the same household with one or more positive cases, contact of index case, healthcare worker or long term care resident) for covid-19.",
      "reason": "Eligibility characteristics are clearly specified: study design (randomised trials), population (people at risk of covid-19, low/high risk groups), interventions/comparators (drugs, vitamins, antibodies vs each other or no prophylaxis), and settings (pre- or post-exposure)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_11",
      "quote": "with no restriction on language of publication",
      "reason": "Language restriction is explicitly addressed (none). Publication status is partially addressed by exclusion of press-releases-only trials (text_13) and inclusion of preprints, but no dissemination year restriction is stated in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": "text_22",
      "quote": "54 Randomised trial with no results",
      "reason": "The flowchart reports excluding randomised trials with no results, but the review does not distinguish exclusion because outcomes were not measured from exclusion because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "compared drugs, therapeutic doses of vitamins, or antibodies for prophylaxis against one another or against no prophylaxis (placebo or standard care, as defined by the researchers)",
      "reason": "Groups for the synthesis are defined by the eligible comparisons (drugs, therapeutic vitamins, antibodies vs one another or no prophylaxis), linked to the review objective of prophylaxis against covid-19, forming the network nodes for the network meta-analysis."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": "text_13",
      "quote": "We excluded randomised trials published only as press releases and trials that evaluated vaccination, nutrition, and non-drug supportive care interventions.",
      "reason": "Notable exclusions (vaccination, nutrition, non-drug supportive care, press-release-only trials) are listed but no rationale for these restrictions is provided in the retrieved evidence."
    }
  ],
  "confidence": 82
}

